import importlib
import json
import os
import shutil
import socket
import sys

PAIR = ("192.168.3.5", "192.168.3.250")
INTERFACE = "eth0"
CAPTURE_TOOLS = ("tcpdump", "tshark", "dumpcap")
CONNTRACK_PATHS = ("/proc/net/nf_conntrack", "/proc/net/ip_conntrack")


def check_raw_socket():
    """Test capture socket creation and interface binding; receive no packets."""
    if not hasattr(socket, "AF_PACKET"):
        return {"available": False, "reason": "AF_PACKET is not supported by this platform"}
    sock = None
    try:
        sock = socket.socket(socket.AF_PACKET, socket.SOCK_RAW, socket.htons(0x0003))
        sock.bind((INTERFACE, 0))
        return {
            "available": True,
            "interface": INTERFACE,
            "detail": "AF_PACKET raw socket opened and bound; no receive operation was performed",
        }
    except OSError as exc:
        return {
            "available": False,
            "interface": INTERFACE,
            "error_type": type(exc).__name__,
            "error": str(exc),
        }
    finally:
        if sock is not None:
            sock.close()


def check_conntrack_files():
    results = []
    for path in CONNTRACK_PATHS:
        item = {"path": path, "exists": os.path.exists(path)}
        if item["exists"]:
            try:
                with open(path, "rb") as source:
                    source.read(0)
                item["readable"] = True
                item["detail"] = "Opened successfully; contents were not read"
            except OSError as exc:
                item["readable"] = False
                item["error_type"] = type(exc).__name__
                item["error"] = str(exc)
        else:
            item["readable"] = False
        results.append(item)
    return results


def main():
    result = {
        "purpose": "Check passive traffic-metadata observation capability; do not alter traffic or collect payloads",
        "pair": list(PAIR),
        "interface": INTERFACE,
        "interface_present": os.path.isdir("/sys/class/net/" + INTERFACE),
        "raw_packet_socket_check": check_raw_socket(),
        "capture_tool_probes": [],
        "conntrack_metadata_sources": check_conntrack_files(),
        "traffic_observed": False,
        "limitations": [
            "Opening and binding a packet socket is an access check only; no packets were received.",
            "Tool presence or interface listing alone does not prove traffic exchange or guarantee a future observation.",
        ],
    }

    helper = None
    helper_error = None
    try:
        helper = importlib.import_module("framework_evidence")
    except Exception as exc:
        helper_error = {"error_type": type(exc).__name__, "error": str(exc)}

    for name in CAPTURE_TOOLS:
        executable = shutil.which(name)
        probe = {"tool": name, "executable": executable, "available": executable is not None}
        if executable and helper is not None and hasattr(helper, "run_tool"):
            try:
                # Interface enumeration is a non-capturing capability probe.
                probe["evidence_envelope"] = helper.run_tool([executable, "-D"])
            except Exception as exc:
                probe["probe_error"] = {"error_type": type(exc).__name__, "error": str(exc)}
        elif executable:
            probe["probe_error"] = helper_error or {"error": "framework_evidence.run_tool unavailable"}
        result["capture_tool_probes"].append(probe)

    if helper_error is not None:
        result["evidence_helper_import_error"] = helper_error
    print(json.dumps(result, sort_keys=True, default=str))


if __name__ == "__main__":
    main()

