import json
import os
import pathlib
import re
import sys

PAIR = ("192.168.3.5", "192.168.3.250")
SYS_NET = pathlib.Path("/sys/class/net")
CONNTRACK_FILES = ("/proc/net/nf_conntrack", "/proc/net/ip_conntrack")


def read_text(path):
    try:
        return {"status": "readable", "value": path.read_text(errors="replace").strip()}
    except OSError as exc:
        return {"status": "inaccessible_or_missing", "error": str(exc)}


def inspect_interfaces():
    result = []
    try:
        names = sorted(p.name for p in SYS_NET.iterdir())
    except OSError as exc:
        return {"status": "inaccessible", "error": str(exc), "interfaces": []}

    for name in names:
        base = SYS_NET / name
        item = {"name": name}
        for key in ("operstate", "address", "ifindex"):
            item[key] = read_text(base / key)
        try:
            item["flags"] = read_text(base / "flags")
            item["bridge_device"] = (base / "bridge").is_dir()
            item["bridge_port"] = (base / "brport").is_dir()
            master = base / "master"
            item["master"] = os.path.basename(os.path.realpath(master)) if master.exists() else None
            bridge_dir = base / "brif"
            if bridge_dir.is_dir():
                try:
                    item["bridge_ports"] = sorted(p.name for p in bridge_dir.iterdir())
                    item["bridge_ports_status"] = "readable"
                except OSError as exc:
                    item["bridge_ports"] = []
                    item["bridge_ports_status"] = "inaccessible: " + str(exc)
        except OSError as exc:
            item["inspection_error"] = str(exc)
        result.append(item)
    return {"status": "checked", "interfaces": result}


def inspect_conntrack():
    results = []
    for filename in CONNTRACK_FILES:
        path = pathlib.Path(filename)
        entry = {"path": filename, "status": None}
        try:
            matched = []
            lines_read = 0
            with path.open("r", errors="replace") as stream:
                for line in stream:
                    lines_read += 1
                    if PAIR[0] in line and PAIR[1] in line:
                        # Conntrack entries contain flow metadata, not application payload.
                        matched.append(line.strip())
            entry.update({"status": "readable", "lines_read": lines_read,
                          "matching_pair_record_count": len(matched),
                          "matching_pair_records": matched})
        except FileNotFoundError as exc:
            entry.update({"status": "missing", "error": str(exc)})
        except PermissionError as exc:
            entry.update({"status": "access_denied", "error": str(exc)})
        except OSError as exc:
            entry.update({"status": "read_error", "error": str(exc)})
        results.append(entry)
    return results


def inspect_tc(interfaces):
    try:
        import framework_evidence
    except Exception as exc:
        return {"status": "helper_import_failed", "error": repr(exc), "tool_runs": []}

    runs = []
    names = [i["name"] for i in interfaces.get("interfaces", []) if i.get("name") != "lo"]
    if interfaces.get("status") != "checked":
        return {"status": "incomplete_interface_inventory", "tool_runs": runs}
    for name in names:
        for args in (
            ["tc", "-j", "qdisc", "show", "dev", name],
            ["tc", "-j", "filter", "show", "dev", name, "ingress"],
            ["tc", "-j", "filter", "show", "dev", name, "egress"],
        ):
            try:
                envelope = framework_evidence.run_tool(args)
                runs.append({"requested_argv": args, "evidence_envelope": envelope})
            except Exception as exc:
                runs.append({"requested_argv": args, "helper_error": repr(exc)})
    return {"status": "checked" if runs or not names else "no_checks_run", "tool_runs": runs}


def main():
    interfaces = inspect_interfaces()
    conntrack = inspect_conntrack()
    tc = inspect_tc(interfaces)
    readable_conntrack = [x for x in conntrack if x["status"] == "readable"]
    matched_count = sum(x.get("matching_pair_record_count", 0) for x in readable_conntrack)
    report = {
        "evidence_version": 1,
        "scope_pair": list(PAIR),
        "method": "read-only local interface, bridge, conntrack metadata, and tc configuration inspection; no packet capture or payload collection",
        "interfaces": interfaces,
        "conntrack_checks": conntrack,
        "tc_configuration_checks": tc,
        "assessment": {
            "accessible_conntrack_facility": bool(readable_conntrack),
            "pair_records_in_readable_conntrack_facilities": matched_count,
            "pair_association_observed_in_conntrack": matched_count > 0,
            "limitations": [
                "Conntrack is local connection-tracking state, not proof of a mirrored feed; an empty snapshot does not establish that no exchange occurred.",
                "Interface and bridge configuration show local topology/configuration only; they do not prove that traffic between the pair is visible here.",
                "tc command errors or missing output leave that interface check incomplete; no other visibility source is inferred from tool inventory.",
            ],
        },
    }
    print(json.dumps(report, sort_keys=True))


if __name__ == "__main__":
    main()

