import datetime
import glob
import json
import os
import re

PAIR = {"192.168.3.5", "192.168.3.250"}
CONNTRACK_PATHS = ["/proc/net/nf_conntrack", "/proc/net/ip_conntrack"]
ZEEK_PATHS = [
    "/var/log/zeek/current/conn.log",
    "/opt/zeek/logs/current/conn.log",
    "/var/log/zeek/conn.log",
]
COLLECTOR_NAMES = {
    "zeek", "suricata", "conntrackd", "softflowd", "nfcapd",
    "pmacctd", "ntopng", "tcpdump", "tshark",
}


def check_conntrack(path):
    result = {"source": path, "kind": "local kernel connection-tracking table"}
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as stream:
            result["status"] = "readable"
            result["matching_entry_count"] = 0
            for line in stream:
                # Emit only tuple metadata, never the raw table entry.
                addresses = re.findall(r"\b(?:src|dst)=([0-9]{1,3}(?:\.[0-9]{1,3}){3})\b", line)
                if PAIR.issubset(set(addresses)):
                    result["matching_entry_count"] += 1
            result["coverage_note"] = (
                "This is the local host's connection-tracking view; it does not establish "
                "network-wide visibility."
            )
    except FileNotFoundError:
        result["status"] = "not present"
    except PermissionError as exc:
        result.update(status="access denied", detail=str(exc))
    except OSError as exc:
        result.update(status="read error", detail=str(exc))
    return result


def check_zeek(path):
    result = {"source": path, "kind": "Zeek connection metadata log"}
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as stream:
            result["status"] = "readable"
            result["matching_record_count"] = 0
            result["sample_matching_records"] = []
            fields = None
            for line in stream:
                if line.startswith("#fields\t"):
                    fields = line.rstrip("\r\n").split("\t")[1:]
                    continue
                if line.startswith("#") or not fields:
                    continue
                values = line.rstrip("\r\n").split("\t")
                if len(values) != len(fields):
                    continue
                row = dict(zip(fields, values))
                endpoints = {row.get("id.orig_h", ""), row.get("id.resp_h", "")}
                if not PAIR.issubset(endpoints):
                    continue
                result["matching_record_count"] += 1
                if len(result["sample_matching_records"]) < 10:
                    result["sample_matching_records"].append({
                        key: row.get(key) for key in
                        ("ts", "proto", "id.orig_h", "id.orig_p", "id.resp_h", "id.resp_p", "conn_state")
                        if key in row
                    })
    except FileNotFoundError:
        result["status"] = "not present"
    except PermissionError as exc:
        result.update(status="access denied", detail=str(exc))
    except OSError as exc:
        result.update(status="read error", detail=str(exc))
    return result


def running_collectors():
    found = []
    errors = []
    for proc in glob.glob("/proc/[0-9]*/comm"):
        try:
            with open(proc, "r", encoding="utf-8", errors="replace") as stream:
                name = stream.read(256).strip()
            if name.lower() in COLLECTOR_NAMES:
                found.append({"process_name": name, "pid": proc.split("/")[2]})
        except (OSError, PermissionError):
            continue
    return {"checked": "process names in /proc only", "matching_processes": found,
            "note": "A process name alone does not verify its configuration, authorization, or endpoint coverage."}


def main():
    report = {
        "checked_at_utc": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "target_pair": sorted(PAIR),
        "scope": "Local read-only metadata sources only; no endpoint probes or payload collection.",
        "sources": [check_conntrack(path) for path in CONNTRACK_PATHS]
                   + [check_zeek(path) for path in ZEEK_PATHS],
        "collector_process_check": running_collectors(),
        "limitations": [
            "Only the explicitly listed local sources and process names were checked.",
            "Absent or unreadable sources and no matching records do not establish that other configured sources are unavailable.",
            "Local kernel state and logs do not by themselves establish complete or current network-wide coverage."
        ]
    }
    print(json.dumps(report, sort_keys=True))


if __name__ == "__main__":
    main()

