#!/usr/bin/env python3
"""Read-only discovery of local packet-observation prerequisites.

Does not contact targets, transmit or receive packets, or change system state.
"""
import errno
import json
import os
import shutil
import socket
import time

CAPABILITIES = {12: "CAP_NET_ADMIN", 13: "CAP_NET_RAW"}
CANDIDATES = [
    "ettercap", "bettercap", "arpspoof", "tcpdump", "tshark",
    "dumpcap", "nft", "iptables", "ip",
]


def read_capabilities():
    result = {name: {"effective": None, "permitted": None} for name in CAPABILITIES.values()}
    try:
        with open("/proc/self/status", "r", encoding="ascii", errors="replace") as f:
            status = dict(line.rstrip("\n").split(":", 1) for line in f if ":" in line)
        for field, key in (("CapEff", "effective"), ("CapPrm", "permitted")):
            raw = status.get(field)
            if raw is None:
                continue
            mask = int(raw.strip(), 16)
            for number, name in CAPABILITIES.items():
                result[name][key] = bool(mask & (1 << number))
        return {"status": "read", "capabilities": result}
    except Exception as exc:
        return {"status": "error", "error": f"{type(exc).__name__}: {exc}", "capabilities": result}


def check_packet_socket():
    if not hasattr(socket, "AF_PACKET"):
        return {"status": "unsupported", "detail": "Python/platform has no AF_PACKET"}
    sock = None
    try:
        # Creating and immediately closing a socket tests permission only; no
        # receive call, packet transmission, or target interaction is performed.
        sock = socket.socket(socket.AF_PACKET, socket.SOCK_RAW, socket.htons(3))
        return {"status": "created_and_closed", "detail": "No packets were read or sent"}
    except OSError as exc:
        return {"status": "error", "errno": exc.errno,
                "error": errno.errorcode.get(exc.errno, "OSError"), "detail": str(exc)}
    finally:
        if sock is not None:
            sock.close()


def check_candidates():
    found = []
    absent = []
    for name in CANDIDATES:
        path = shutil.which(name)
        record = {"name": name, "path": path}
        (found if path else absent).append(record)
    return {"found_in_path": found, "not_found_in_path": absent,
            "note": "Presence in PATH is not a functional test; this candidate list is not exhaustive."}


def read_forwarding_setting():
    path = "/proc/sys/net/ipv4/ip_forward"
    try:
        with open(path, "r", encoding="ascii") as f:
            value = f.read(64).strip()
        return {"status": "read", "value": value, "path": path,
                "note": "Read only; this does not establish permission to change it."}
    except Exception as exc:
        return {"status": "error", "path": path,
                "error": f"{type(exc).__name__}: {exc}"}


def main():
    interfaces = []
    interface_error = None
    try:
        interfaces = [{"index": idx, "name": name} for idx, name in socket.if_nameindex()]
    except Exception as exc:
        interface_error = f"{type(exc).__name__}: {exc}"

    caps = read_capabilities()
    packet_socket = check_packet_socket()
    candidates = check_candidates()
    cap_data = caps.get("capabilities", {})
    has_raw = cap_data.get("CAP_NET_RAW", {}).get("effective") is True
    has_admin = cap_data.get("CAP_NET_ADMIN", {}).get("effective") is True
    found = candidates["found_in_path"]

    if found and has_raw and has_admin and packet_socket["status"] == "created_and_closed":
        assessment = "candidate_and_current_privileges_observed; functionality_unverified"
    elif packet_socket["status"] == "error" and packet_socket.get("errno") in (errno.EPERM, errno.EACCES):
        assessment = "current_process_packet_socket_permission_denied; other_mechanisms_and_privilege_context_unverified"
    else:
        assessment = "indeterminate"

    report = {
        "checked_at_unix": time.time(),
        "scope": "Local read-only capability checks; no target probes or traffic changes",
        "effective_uid": os.geteuid() if hasattr(os, "geteuid") else None,
        "capabilities": caps,
        "af_packet_raw_socket_permission_probe": packet_socket,
        "candidate_executables": candidates,
        "interfaces": {"status": "read" if interface_error is None else "error",
                        "names": interfaces, "error": interface_error},
        "ipv4_forwarding_setting": read_forwarding_setting(),
        "assessment": assessment,
        "limitations": [
            "Only the listed executable names, current process capabilities, AF_PACKET socket creation, interface names, and forwarding setting were checked.",
            "No candidate executable was run; presence does not verify function, configuration, or suitability for the scoped observation.",
            "A denied socket or absent effective capability describes this process at check time, not whether another authorized process or facility exists.",
            "No target connectivity, traffic visibility, interception functionality, or automatic cleanup was tested.",
        ],
    }
    print(json.dumps(report, sort_keys=True))


if __name__ == "__main__":
    main()

