import datetime
import json
import sys

TARGETS = {
    "192.168.3.5": "f2:af:e9:9b:59:8d",
    "192.168.3.250": "06:58:74:3f:cd:af",
}
COMMANDS = {
    "neighbors": ["ip", "-j", "neigh", "show"],
    "interfaces": ["ip", "-j", "addr", "show"],
    "routes": ["ip", "-j", "route", "show"],
}


def decode_envelope(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except Exception:
            return None
    return value if isinstance(value, (dict, list)) else None


def find_stdout(value):
    """Find a tool stdout string without discarding the original envelope."""
    if isinstance(value, dict):
        if isinstance(value.get("stdout"), str):
            return value["stdout"]
        for child in value.values():
            found = find_stdout(child)
            if found is not None:
                return found
    elif isinstance(value, list):
        for child in value:
            found = find_stdout(child)
            if found is not None:
                return found
    return None


def parse_json_stdout(envelope):
    text = find_stdout(envelope)
    if text is None:
        return None
    try:
        return json.loads(text)
    except Exception:
        return None


def main():
    report = {
        "observed_at_utc": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "scope": "Read-only local neighbor-table and interface/route inspection; no packets sent and no entries changed.",
        "prior_candidate_mac_baseline": TARGETS,
        "tool_runs": {},
        "target_comparison": {},
        "limitations": [
            "Neighbor entries and their states are local observations, not verification of either endpoint's current ARP state or remote restoration.",
            "A missing entry is not evidence that an endpoint is absent; a matching or stale entry does not prove remote state.",
            "The snapshot timestamp is recorded here. Any freshness indicators supplied by ip are retained in the raw output; no age is inferred when none is reported."
        ],
    }
    try:
        from framework_evidence import run_tool
    except Exception as exc:
        report["helper_error"] = "Could not import supplied framework_evidence.run_tool: " + repr(exc)
        print(json.dumps(report, sort_keys=True))
        return

    parsed = {}
    for name, argv in COMMANDS.items():
        try:
            envelope = run_tool(argv)
            report["tool_runs"][name] = {"argv": argv, "evidence_envelope": envelope}
            parsed[name] = parse_json_stdout(envelope)
        except Exception as exc:
            report["tool_runs"][name] = {"argv": argv, "error": repr(exc)}
            parsed[name] = None

    neighbors = parsed.get("neighbors")
    if isinstance(neighbors, list):
        entries_by_ip = {}
        for entry in neighbors:
            if isinstance(entry, dict) and entry.get("dst") in TARGETS:
                entries_by_ip.setdefault(entry["dst"], []).append(entry)
        for ip, baseline in TARGETS.items():
            entries = entries_by_ip.get(ip, [])
            report["target_comparison"][ip] = {
                "prior_candidate_mac": baseline,
                "local_entries_observed": entries,
                "comparison": [
                    {
                        "observed_mac": entry.get("lladdr"),
                        "matches_prior_candidate": (
                            isinstance(entry.get("lladdr"), str)
                            and entry["lladdr"].lower() == baseline
                        ),
                        "neighbor_state": entry.get("state"),
                        "interface": entry.get("dev"),
                    }
                    for entry in entries
                ],
                "result": "entry observed" if entries else "no matching local entry in parsed snapshot",
            }
    else:
        report["target_comparison_status"] = (
            "Could not parse neighbor command JSON from the evidence envelope; raw envelope is retained."
        )

    print(json.dumps(report, sort_keys=True))


if __name__ == "__main__":
    main()

