#!/usr/bin/env python3
"""Read relevant local configuration declarations without reading traffic or logs."""
import json
import os
import re
import stat

ROOTS = ("/etc", "/usr/local/etc")
CONFIG_EXTENSIONS = {
    ".conf", ".cfg", ".ini", ".yaml", ".yml", ".toml", ".json",
    ".xml", ".properties", ".service", ".socket", ".target",
}
SOURCE_TERMS = re.compile(
    r"\b(?:netflow|ipfix|sflow|pmacct|nprobe|softflowd|nfcapd|nfdump|"
    r"argus|ra\s*|yaf|silk|ntopng|flowd|flow-tools|flowmeter|"
    r"connection[-_ ](?:tracking|metadata|logging)|flow[-_ ](?:export|record|log|metadata))\b",
    re.IGNORECASE,
)
DECLARATION_TERMS = re.compile(
    r"\b(?:flow|netflow|ipfix|sflow|connection[-_ ](?:tracking|metadata|log)|"
    r"exporter|collector|output|destination|sink|spool|record[-_ ]file)\b",
    re.IGNORECASE,
)
OUTPUT_KEY = re.compile(
    r"(?:output(?:[-_. ](?:file|path|directory|dir|destination))?|"
    r"destination|sink|spool(?:[-_. ](?:file|directory|dir))?|"
    r"record[-_. ]file|log[-_. ](?:file|path))\s*[:=]\s*",
    re.IGNORECASE,
)
PATH_TOKEN = re.compile(r"(?<![A-Za-z0-9])(?:/[^\s\"'`,;]+|\.?\.?/[A-Za-z0-9_./-]+)")
SECRET_ASSIGNMENT = re.compile(
    r"(?i)(\b(?:password|passwd|secret|token|api[_-]?key|private[_-]?key|"
    r"credential|auth(?:orization)?)\b\s*[:=]\s*)([^\s,;]+)"
)


def is_relevant_config(path):
    low = path.lower()
    base = os.path.basename(low)
    if any(part in {"zeek", "logs", "log", "run", "cache", "spool", "data"}
           for part in low.split(os.sep)):
        return False
    if any(word in base for word in ("passwd", "shadow", "secret", "credential", "private", "id_rsa")):
        return False
    if base.endswith((".pem", ".key", ".crt", ".cer", ".p12", ".pfx", ".db", ".sqlite")):
        return False
    if base.endswith(tuple(CONFIG_EXTENSIONS)):
        return True
    # Include extensionless declarations in conventional telemetry-related config dirs/files.
    return bool(re.search(r"(?:^|[/_.-])(?:pmacct|nprobe|softflowd|nfcapd|nfdump|argus|yaf|silk|ntopng|flowd|netflow|ipfix|sflow)(?:[/_.-]|$)", low))


def safe_output_refs(line):
    refs = []
    for match in OUTPUT_KEY.finditer(line):
        tail = line[match.end():match.end() + 500]
        # Never surface values from secret-bearing assignments or URL credentials.
        tail = SECRET_ASSIGNMENT.sub(r"\1[REDACTED]", tail)
        for token in PATH_TOKEN.findall(tail):
            token = token.rstrip(")]}>.:")
            low = token.lower()
            if "suricata" in low and "eve.json" in low:
                continue  # The checked Suricata flow-log output is out of scope.
            if token and token not in refs:
                refs.append(token[:300])
    return refs


def main():
    files_checked = 0
    lines_checked = 0
    unreadable = []
    roots = []
    declarations = []
    excluded_zeek = 0
    for root in ROOTS:
        exists = os.path.isdir(root)
        roots.append({"path": root, "present": exists})
        if not exists:
            continue
        for current, dirs, names in os.walk(root, followlinks=False):
            dirs[:] = sorted(d for d in dirs if d.lower() != "zeek" and d.lower() not in {"logs", "log", "run", "cache", "spool", "data"})
            for name in sorted(names):
                path = os.path.join(current, name)
                if "/zeek/" in path.lower():
                    excluded_zeek += 1
                    continue
                try:
                    mode = os.stat(path, follow_symlinks=False).st_mode
                    if not stat.S_ISREG(mode) or not is_relevant_config(path):
                        continue
                    files_checked += 1
                    with open(path, "r", encoding="utf-8", errors="replace") as stream:
                        for number, raw in enumerate(stream, 1):
                            lines_checked += 1
                            line = raw.strip()
                            if not line or line.startswith(("#", "//", "<!--", ";")):
                                continue
                            if not DECLARATION_TERMS.search(line):
                                continue
                            # Exclude explicitly disallowed source declarations.
                            if re.search(r"\b(?:AF_PACKET|conntrack|zeek)\b", line, re.IGNORECASE):
                                continue
                            source_terms = sorted(set(m.group(0).lower() for m in SOURCE_TERMS.finditer(line)))
                            if not source_terms:
                                continue
                            # Only report path references associated with output-like keys.
                            outputs = safe_output_refs(line)
                            declarations.append({
                                "config_path": path,
                                "line": number,
                                "source_terms": source_terms,
                                "associated_output_references": outputs,
                            })
                except (OSError, UnicodeError) as exc:
                    unreadable.append({"path": path, "error": type(exc).__name__})
    result = {
        "inspection": "read_only_local_configuration_declarations",
        "roots": roots,
        "files_checked": files_checked,
        "lines_checked": lines_checked,
        "distinct_source_declarations": declarations,
        "matching_declaration_found": bool(declarations),
        "unreadable_files": unreadable,
        "coverage_notes": [
            "Only selected configuration-like files under present /etc and /usr/local/etc roots were examined.",
            "Zeek paths, log/data/spool directories, secret/key-like files, and non-configuration files were excluded.",
            "No payload contents, log records, process names, or network state were inspected.",
            "Absence of a declaration in these checked files does not rule out unchecked roots or other configurations.",
            "Output references are reported only when an output-like setting contains a path; other output formats may not be captured.",
        ],
        "zeek_path_entries_excluded": excluded_zeek,
        "suricata_checked_flow_log_reference": "excluded",
    }
    print(json.dumps(result, ensure_ascii=False, sort_keys=True))


if __name__ == "__main__":
    main()

