    Path("/lib/systemd/system"),
    Path("/usr/local/lib/systemd/system"),
]
CANDIDATE = re.compile(r"\b(flow|netflow|connection|metadata|telemetry|traffic)\b", re.I)
EXCLUDED = re.compile(r"\b(af[_ -]?packet|conntrack|zeek|suricata)\b", re.I)
OUTPUT_KEYS = {"standardoutput", "standarderror", "logsdirectory", "statedirectory", "runtimedirectory"}


def parse_declaration(path):
    """Read only descriptive and output-directory directives; omit command/env lines."""
    result = {"descriptions": [], "references": []}
    try:
        with path.open("r", encoding="utf-8", errors="replace") as stream:
            for raw in stream:
                line = raw.strip()
                if not line or line.startswith(("#", ";")) or "=" not in line:
                    continue
                key, value = line.split("=", 1)
                key = key.strip().lower()
                value = value.strip()
                if key == "description" and value:
                    result["descriptions"].append(value)
                elif key in OUTPUT_KEYS and value:
                    # Report only the destination portion of file/append output modes.
                    if key in ("standardoutput", "standarderror"):
                        mode, sep, destination = value.partition(":")
                        if sep and mode.lower() in ("file", "append"):
                            value = destination.strip()
                    result["references"].append({"directive": key, "value": value})
    except (OSError, UnicodeError) as exc:
        return None, f"{type(exc).__name__}: {exc}"
    return result, None


locations = []
files_checked = 0
unreadable = []
candidates = []
seen = set()

for root in ROOTS:
    location = {"path": str(root), "present": root.is_dir()}
    locations.append(location)
    if not location["present"]:
        continue
    try:
        entries = sorted(root.iterdir(), key=lambda p: p.name)
    except OSError as exc:
        unreadable.append({"path": str(root), "error": f"{type(exc).__name__}: {exc}"})
        continue

    for unit in entries:
        if not unit.name.endswith(".service") or not unit.is_file():
            continue
        try:
            resolved = unit.resolve(strict=True)
        except OSError as exc:
            unreadable.append({"path": str(unit), "error": f"{type(exc).__name__}: {exc}"})
            continue
        if resolved in seen:
            continue
        seen.add(resolved)
        files_checked += 1
        parsed, error = parse_declaration(unit)
        if error:
            unreadable.append({"path": str(unit), "error": error})
            continue
        description = " ".join(parsed["descriptions"])
        if not description or not CANDIDATE.search(description) or EXCLUDED.search(description):
            continue

        refs = list(parsed["references"])
        dropin_dir = root / (unit.name + ".d")
        if dropin_dir.is_dir():
            try:
                dropins = sorted(dropin_dir.iterdir(), key=lambda p: p.name)
            except OSError as exc:
                unreadable.append({"path": str(dropin_dir), "error": f"{type(exc).__name__}: {exc}"})
