                seen.add(dropin_resolved)
                files_checked += 1
                extra, error = parse_declaration(dropin)
                if error:
                    unreadable.append({"path": str(dropin), "error": error})
                else:
                    refs.extend(extra["references"])

        candidates.append({
            "declaration": str(unit),
            "description_matches_topic": True,
            "output_or_directory_references": refs,
        })

