#!/usr/bin/env python3
"""Read additional safe output/metadata directives in vendor systemd units."""
import json
import os
import re
from pathlib import Path

ROOTS = (
    Path('/usr/lib/systemd/system'),
    Path('/lib/systemd/system'),
    Path('/usr/local/lib/systemd/system'),
)
# These directives were checked previously; do not report them again.
PREVIOUSLY_CHECKED = {
    'standardoutput', 'standarderror', 'logsdirectory',
    'statedirectory', 'runtimedirectory',
}
# Never report or use executable/environment directive contents.
FORBIDDEN = re.compile(r'^(?:exec|environment|passenvironment|unsetenvironment)', re.I)
DESCRIPTION_MATCH = re.compile(
    r'flow|connection|metadata|telemetry|network|traffic|capture', re.I
)
EXCLUDED = re.compile(
    r'zeek|suricata|conntrack|af[_ -]?packet|secret|credential|private[_-]?key',
    re.I,
)
DIRECTIVE_MATCH = re.compile(r'log|output|metadata|trace|flow|connection|journal', re.I)
SECRET_VALUE = re.compile(r'password|passwd|token|secret|credential|private[_-]?key', re.I)
PATH_LIKE = re.compile(r'(^|[=,:\s])(?:/|\./|\.\./|%[A-Za-z_]+)')


def unit_files(root):
    """Yield service declarations and drop-ins, without following directory symlinks."""
    if not root.is_dir():
        return
    for base, dirs, files in os.walk(root, followlinks=False):
        dirs[:] = sorted(d for d in dirs if not EXCLUDED.search(d))
        for name in sorted(files):
            if name.endswith('.service') or ('.service.d' in base and name.endswith('.conf')):
                path = Path(base) / name
                try:
                    if path.is_file() and not EXCLUDED.search(str(path)):
                        yield path
                except OSError:
                    continue


def inspect(path):
    """Read descriptions and safe candidate keys; ignore forbidden key contents."""
    descriptions = []
    matches = []
    section = ''
    with path.open('r', encoding='utf-8', errors='replace') as stream:
        for number, raw in enumerate(stream, 1):
            line = raw.strip()
            if not line or line.startswith(('#', ';')):
                continue
            if line.startswith('[') and line.endswith(']'):
                section = line[1:-1].strip().lower()
                continue
            if '=' not in line:
                continue
            key, value = line.split('=', 1)
            key = key.strip()
            # Do not inspect, retain, or report executable/environment values.
            if FORBIDDEN.match(key):
                continue
            val = value.strip()
            if section == 'unit' and key.lower() == 'description':
                descriptions.append(val)
            lowered = key.lower()
            if (section == 'service' and lowered not in PREVIOUSLY_CHECKED
                    and DIRECTIVE_MATCH.search(key)):
                if SECRET_VALUE.search(val):
                    rendered = '[redacted: secret-like value]'
                elif len(val) > 400:
                    rendered = val[:400] + '[truncated]'
                else:
                    rendered = val
                matches.append({
                    'line': number,
                    'section': section,
                    'directive': key,
                    'value': rendered,
                    'path_like_reference_observed': bool(PATH_LIKE.search(val)),
                })
    return descriptions, matches


def main():
    seen = set()
    candidates = []
    unreadable = []
    roots = []
    for root in ROOTS:
        roots.append({'path': str(root), 'present': root.is_dir()})
        for path in unit_files(root) or ():
            try:
                resolved = path.resolve(strict=True)
                identity = str(resolved)
                if identity in seen:
                    continue
                seen.add(identity)
                descriptions, directives = inspect(path)
                if any(DESCRIPTION_MATCH.search(text) for text in descriptions):
                    candidates.append({
                        'declaration': str(path),
                        'matching_descriptions': [
                            text for text in descriptions if DESCRIPTION_MATCH.search(text)
                        ],
                        'additional_output_metadata_directives': directives,
                    })
            except (OSError, UnicodeError) as exc:
                unreadable.append({'path': str(path), 'error': str(exc)})
    print(json.dumps({
        'inspection': 'read_only_additional_vendor_systemd_output_references',
        'roots': roots,
        'description_matched_declarations_examined': len(candidates),
        'declarations': candidates,
        'unreadable_declarations': unreadable,
        'coverage_notes': [
            'Examined service unit files and service drop-ins under the listed vendor systemd roots only.',
            'Selected declarations by safe Unit Description text; this selection may not reproduce the earlier candidate set.',
            'Did not report previously checked directives or inspect executable/environment directive values.',
            'Reported only matching safe directive keys in the Service section; other output mechanisms may not be represented.',
            'No referenced payloads, logs, secrets, process lists, or network state were inspected.',
            'Absence in this result does not establish absence in unchecked declarations, roots, or output mechanisms.',
        ],
    }, sort_keys=True))


if __name__ == '__main__':
    main()

