import json
import os
import re
import stat

MANIFEST_DIR = "/var/lib/dpkg/info"
VENDOR_ROOTS = ("/usr/lib/", "/usr/libexec/", "/usr/share/", "/lib/", "/opt/")
SERVICE_COMPONENTS = {
    "init", "init.d", "rc", "rc.d", "runit", "s6", "openrc",
    "service", "services", "supervise"
}
EXCLUDED_PREFIXES = ("/etc/", "/usr/local/", "/usr/local/etc/")
TOPIC_RE = re.compile(
    r"flow|netflow|ipfix|zeek|suricata|argus|"
    r"conn(?:ection)?[ _-]?(?:track|metadata|meta|log|record|data)",
    re.IGNORECASE,
)
ABS_PATH_RE = re.compile(r"(?<![A-Za-z0-9_.-])/(?:[A-Za-z0-9_.@+:-]+/)*[A-Za-z0-9_.@+:-]*")


def is_excluded(path):
    normalized = os.path.normpath(path)
    return any(normalized == p.rstrip("/") or normalized.startswith(p) for p in EXCLUDED_PREFIXES)


def is_vendor_path(path):
    normalized = os.path.normpath(path)
    return normalized.startswith(VENDOR_ROOTS) and not is_excluded(normalized + "/")


def is_candidate_path(path):
    normalized = os.path.normpath(path)
    if not is_vendor_path(normalized):
        return False
    parts = normalized.strip("/").split("/")
    if "systemd" in parts:
        return False
    if not SERVICE_COMPONENTS.intersection(parts[:-1]):
        return False
    return True


def main():
    result = {
        "manifest_source": MANIFEST_DIR,
        "manifest_files_read": 0,
        "manifest_errors": [],
        "excluded_manifest_paths_skipped": 0,
        "non_vendor_manifest_paths_skipped": 0,
        "systemd_manifest_paths_skipped": 0,
        "candidate_paths_discovered": 0,
        "declarations_inspected": [],
        "coverage_notes": [
            "Read Debian dpkg .list package file manifests only; no package payload was extracted.",
            "Candidate selection is limited to manifest-listed files under vendor roots with non-systemd service-location path components.",
            "Excluded /etc, /usr/local, and systemd paths were not opened or traversed.",
            "Only declaration files were read. Matching source lines are not emitted; reported references are extracted paths and line numbers.",
            "This does not establish coverage of unmanifested files, other package formats, or service mechanisms outside the inspected locations."
        ],
        "access_or_coverage_limitations": []
    }
    candidates = set()
    try:
        manifest_names = sorted(os.listdir(MANIFEST_DIR))
    except OSError as exc:
        result["access_or_coverage_limitations"].append(
            {"path": MANIFEST_DIR, "error": str(exc)}
        )
        manifest_names = []

    for name in manifest_names:
        if not name.endswith(".list"):
            continue
        manifest_path = os.path.join(MANIFEST_DIR, name)
        try:
            with open(manifest_path, "r", encoding="utf-8", errors="replace") as manifest:
                result["manifest_files_read"] += 1
                for raw in manifest:
                    entry = raw.rstrip("\n")
                    if not entry.startswith("/"):
                        continue
                    path = os.path.normpath(entry)
                    if is_excluded(path):
                        result["excluded_manifest_paths_skipped"] += 1
                        continue
                    if not is_vendor_path(path):
                        result["non_vendor_manifest_paths_skipped"] += 1
                        continue
                    parts = path.strip("/").split("/")
                    if "systemd" in parts:
                        result["systemd_manifest_paths_skipped"] += 1
                        continue
                    if is_candidate_path(path):
                        candidates.add(path)
        except OSError as exc:
            result["manifest_errors"].append({"path": manifest_path, "error": str(exc)})

    result["candidate_paths_discovered"] = len(candidates)
    for path in sorted(candidates):
        record = {"declaration": path, "status": "not_inspected", "metadata_references": [], "error": ""}
        try:
            info = os.lstat(path)
            if not stat.S_ISREG(info.st_mode):
                record["status"] = "skipped_not_regular_file"
            else:
                refs = []
                with open(path, "r", encoding="utf-8", errors="replace") as declaration:
                    for line_number, line in enumerate(declaration, 1):
                        terms = sorted(set(m.group(0).lower() for m in TOPIC_RE.finditer(line)))
                        if not terms:
                            continue
                        referenced_paths = sorted(set(m.group(0).rstrip(".,;:)") for m in ABS_PATH_RE.finditer(line)))
                        refs.append({
                            "line": line_number,
                            "topic_terms": terms,
                            "explicit_paths": referenced_paths
                        })
                record["status"] = "inspected"
                record["metadata_references"] = refs
        except (OSError, UnicodeError) as exc:
            record["status"] = "access_error"
            record["error"] = str(exc)
            result["access_or_coverage_limitations"].append({"path": path, "error": str(exc)})
        result["declarations_inspected"].append(record)

    print(json.dumps(result, sort_keys=True, indent=2))


if __name__ == "__main__":
    main()

