import json
import os
import re
import stat
import sys

# Search conventional vendor-oriented locations only. /etc and all systemd
# declaration directories are deliberately excluded.
ROOTS = [
    "/usr/lib",
    "/usr/libexec",
    "/usr/share",
    "/usr/local/lib",
    "/usr/local/libexec",
    "/usr/local/share",
    "/opt",
]

SERVICE_DIR = re.compile(
    r"^(?:service|services|sv|runit|s6|s6[-_.].*|supervisor|"
    r"init\.d|rc\.d|daemontools|openrc|monit)(?:[-_.].*)?$",
    re.IGNORECASE,
)
TEXT_SUFFIXES = {
    ".conf", ".cfg", ".ini", ".yaml", ".yml", ".toml", ".json",
    ".sh", ".rc", ".inc", ".service", ".init",
}
DECLARATION_BASENAMES = {
    "run", "finish", "down", "supervise", "service", "init",
    "monitrc", "supervisord.conf",
}
FLOW_TERMS = re.compile(
    r"\b(?:flow|netflow|ipfix|conntrack|connection(?:s|[-_ ]metadata)?|"
    r"network|packet|pcap|zeek|suricata|telemetry|metadata)\b",
    re.IGNORECASE,
)
OUTPUT_TERMS = re.compile(
    r"\b(?:output|outputs|log|logs|file|path|directory|dir|state|data|"
    r"spool|database|db|metadata|record|records|write|writefile)\b",
    re.IGNORECASE,
)
PATH_TOKEN = re.compile(
    r"(?<![A-Za-z0-9])(?:/(?:[A-Za-z0-9_.@+~-]+/)*[A-Za-z0-9_.@+~-]*"
    r"|\.{1,2}/(?:[A-Za-z0-9_.@+~-]+/)*[A-Za-z0-9_.@+~-]+)"
)
SENSITIVE = re.compile(r"\b(?:password|passwd|secret|token|api[_-]?key|private[_-]?key)\b", re.I)


def under(path, root):
    try:
        return os.path.commonpath((os.path.abspath(path), os.path.abspath(root))) == os.path.abspath(root)
    except (ValueError, OSError):
        return False


def excluded(path):
    normalized = os.path.abspath(path)
    if under(normalized, "/etc"):
        return True
    parts = normalized.split(os.sep)
    return "systemd" in parts


def walk_error(exc):
    errors.append({"path": getattr(exc, "filename", None), "error": str(exc)})


def declaration_candidate(path, mode):
    name = os.path.basename(path).lower()
    if name in DECLARATION_BASENAMES or os.path.splitext(name)[1] in TEXT_SUFFIXES:
        return True
    # Include extensionless executable scripts only when their first line is a shebang.
    if mode & 0o111:
        try:
            with open(path, "rb") as f:
                return f.readline(4096).startswith(b"#!")
        except OSError as exc:
            errors.append({"path": path, "error": str(exc)})
    return False


errors = []
missing_roots = []
found_service_dirs = set()
examined = set()
relevant = []

for root in ROOTS:
    if not os.path.exists(root):
        missing_roots.append(root)
        continue
    if not os.path.isdir(root):
        errors.append({"path": root, "error": "exists but is not a directory"})
        continue
    for current, dirs, files in os.walk(root, topdown=True, followlinks=False, onerror=walk_error):
        dirs[:] = [d for d in dirs if not excluded(os.path.join(current, d))
                   and not os.path.islink(os.path.join(current, d))]
        if excluded(current):
            dirs[:] = []
            continue
        if SERVICE_DIR.match(os.path.basename(current)):
            found_service_dirs.add(os.path.abspath(current))

# Walk each discovered conventional service directory. A set prevents duplicate
# inspection when conventional service directories are nested.
for service_dir in sorted(found_service_dirs, key=lambda p: (p.count(os.sep), p)):
    for current, dirs, files in os.walk(service_dir, topdown=True, followlinks=False, onerror=walk_error):
        if excluded(current):
            dirs[:] = []
            continue
        dirs[:] = [d for d in dirs if not os.path.islink(os.path.join(current, d))
                   and not excluded(os.path.join(current, d))]
        for name in files:
            path = os.path.abspath(os.path.join(current, name))
            if path in examined or excluded(path) or os.path.islink(path):
                continue
            try:
                st = os.stat(path, follow_symlinks=False)
            except OSError as exc:
                errors.append({"path": path, "error": str(exc)})
                continue
            if not stat.S_ISREG(st.st_mode) or not declaration_candidate(path, st.st_mode):
                continue
            examined.add(path)
            try:
                hits = []
                with open(path, "rb") as f:
                    for line_number, raw in enumerate(f, 1):
                        if b"\x00" in raw:
                            hits = None
                            break
                        text = raw.decode("utf-8", errors="replace")
                        terms = sorted(set(m.group(0).lower() for m in FLOW_TERMS.finditer(text)))
                        if not terms:
                            continue
                        refs = []
                        if OUTPUT_TERMS.search(text) and not SENSITIVE.search(text):
                            refs = sorted(set(m.group(0).rstrip(".,;:)") for m in PATH_TOKEN.finditer(text)))
                        hits.append({
                            "line": line_number,
                            "indicators": terms,
                            "explicit_output_or_metadata_paths": refs,
                        })
                if hits is None:
                    errors.append({"path": path, "error": "binary content; declaration text not assessed"})
                elif hits:
                    relevant.append({"declaration": path, "indicators": hits})
            except OSError as exc:
                errors.append({"path": path, "error": str(exc)})

result = {
    "method": "read-only direct filesystem discovery; no package manifests used",
    "roots_examined": [r for r in ROOTS if os.path.isdir(r)],
    "missing_roots": missing_roots,
    "conventional_non_systemd_service_directories_found": sorted(found_service_dirs),
    "declaration_files_examined": sorted(examined),
    "relevant_declarations_and_references": relevant,
    "metadata_record_contents_inspected": False,
    "coverage_notes": [
        "Search was limited to the listed vendor-oriented roots and conventional service-manager directory names.",
        "Candidate declaration files were selected by declaration-like suffix or conventional service-script name.",
        "The search does not cover unrecognized directory layouts, excluded /etc or systemd locations, or mechanisms without readable declaration files.",
        "Only lines with flow or connection-metadata indicators are reported; paths are extracted only from lines also containing output or metadata terms, with sensitive-looking lines omitted.",
        "No referenced metadata records or payload contents were opened.",
    ],
    "access_or_read_errors": errors,
}
json.dump(result, sys.stdout, ensure_ascii=False, indent=2)
sys.stdout.write("\n")
